WITH scored AS (SELECT id, country, rating, SUM(rating) OVER (PARTITION BY city, country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_rating, NTILE(5) OVER (PARTITION BY country ORDER BY rating DESC, id) rating_bucket FROM suppliers WHERE rating < 1.9), enriched AS (SELECT *, LEAD(running_rating, 1) OVER (PARTITION BY country ORDER BY rating, id) next_running_rating, RANK() OVER (ORDER BY rating DESC NULLS LAST) rating_rank FROM scored), matched_keys AS (SELECT id, country FROM enriched EXCEPT ALL SELECT id, country FROM suppliers WHERE country IN ('US', 'JP', 'SG')), kept_rows AS (SELECT s.* FROM enriched s JOIN matched_keys k ON s.id = k.id AND s.country = k.country), base AS (SELECT *, ROUND(rating_bucket * 1.15, 2) adjusted_rating_bucket, CAST(next_running_rating AS STRING) next_running_rating_str FROM kept_rows WHERE running_rating != 10), grouped AS (SELECT country, CASE WHEN rating_rank >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_rank_tier, ROUND(SUM(next_running_rating) / NULLIF(COUNT(CASE WHEN country = 'UK' THEN 1 END), 0), 2) AS next_running_rating_per_uk, COUNT(*) AS event_count, COUNT_IF(country = 'JP') AS jp_events, COUNT(CASE WHEN country = 'US' THEN 1 END) AS us_count, MIN(rating) AS min_rating FROM base GROUP BY country, CASE WHEN rating_rank >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END) SELECT country, rating_rank_tier, next_running_rating_per_uk, event_count, jp_events, us_count, min_rating FROM grouped ORDER BY next_running_rating_per_uk DESC;
